style.css:
@-moz-document domain("google.com") {
/* Hide the default Google logo */
    img[alt="Google"], .lnXdpd {
        display: none !important;
    }
    
    /* Create a blocky custom text logo */
    body::before {
        content: "GOOGLE";
        font-family: 'Press Start 2P', sans-serif; /* Blocky, pixelated font */
        font-size: 60px;
        color: #fff;
        text-transform: uppercase;
        text-align: center;
        display: block;
        margin: 20px auto;
        width: 100%;
        text-shadow: 3px 3px 0px #ff0000, 6px 6px 0px #0000ff; /* NYC-style vibe */
    }
}
